// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAccount 本人资料
	// (GET /account)
	GetAccount(ctx context.Context, request GetAccountRequestObject) (GetAccountResponseObject, error)
	// UpdateAccount 修改昵称、头像或默认时区
	// (PATCH /account)
	UpdateAccount(ctx context.Context, request UpdateAccountRequestObject) (UpdateAccountResponseObject, error)
	// ChangePassword 登录态修改密码；撤销其他会话，保留当前会话
	// (POST /account/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// ListSessions 本人有效会话
	// (GET /account/sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)
	// RevokeSession 撤销本人指定会话；重复撤销仍成功
	// (DELETE /account/sessions/{session_id})
	RevokeSession(ctx context.Context, request RevokeSessionRequestObject) (RevokeSessionResponseObject, error)
	// CreateAsset 登记私有资产与首次上传尝试，直接返回暂存对象的 PUT 授权；不接受用户指定对象键
	// (POST /assets)
	CreateAsset(ctx context.Context, request CreateAssetRequestObject) (CreateAssetResponseObject, error)
	// AuthorizeAssetDownloads 一次最多 100 个资产；返回各自状态，仅 ready 的带 URL
	// (POST /assets/download-authorizations)
	AuthorizeAssetDownloads(ctx context.Context, request AuthorizeAssetDownloadsRequestObject) (AuthorizeAssetDownloadsResponseObject, error)
	// GetAsset 公开处理状态与已校验元数据；不含对象键与下载地址
	// (GET /assets/{asset_id})
	GetAsset(ctx context.Context, request GetAssetRequestObject) (GetAssetResponseObject, error)
	// ConfirmAssetUpload 按尝试序号确认上传并事务入队校验任务；不能直接宣称 ready
	// (POST /assets/{asset_id}/confirm)
	ConfirmAssetUpload(ctx context.Context, request ConfirmAssetUploadRequestObject) (ConfirmAssetUploadResponseObject, error)
	// AuthorizeAssetDownload 校验归属后签发短期下载授权；仅 ready 资产
	// (GET /assets/{asset_id}/download)
	AuthorizeAssetDownload(ctx context.Context, request AuthorizeAssetDownloadRequestObject) (AuthorizeAssetDownloadResponseObject, error)
	// AuthorizeAssetUpload 续签当前尝试，或在失败/过期后创建新尝试并返回授权
	// (POST /assets/{asset_id}/upload-authorization)
	AuthorizeAssetUpload(ctx context.Context, request AuthorizeAssetUploadRequestObject) (AuthorizeAssetUploadResponseObject, error)
	// RequestEmailChallenge 申请注册或找回密码的邮箱验证码
	// (POST /auth/email-challenges)
	RequestEmailChallenge(ctx context.Context, request RequestEmailChallengeRequestObject) (RequestEmailChallengeResponseObject, error)
	// Login 邮箱密码登录
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout 撤销当前会话并清除浏览器刷新 Cookie
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// ResetPassword 验证码验证后重置密码并撤销全部会话
	// (POST /auth/password-reset)
	ResetPassword(ctx context.Context, request ResetPasswordRequestObject) (ResetPasswordResponseObject, error)
	// Reauthenticate 验证当前密码，本会话近期认证有效 5 分钟
	// (POST /auth/reauthenticate)
	Reauthenticate(ctx context.Context, request ReauthenticateRequestObject) (ReauthenticateResponseObject, error)
	// RefreshSession 轮换刷新令牌并签发新的访问令牌
	// (POST /auth/refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// RegisterAccount 验证邮箱后创建账号并登录
	// (POST /auth/register)
	RegisterAccount(ctx context.Context, request RegisterAccountRequestObject) (RegisterAccountResponseObject, error)
	// ListExpenseCategories 本账号全部有效账单分类
	// (GET /expense-categories)
	ListExpenseCategories(ctx context.Context, request ListExpenseCategoriesRequestObject) (ListExpenseCategoriesResponseObject, error)
	// CreateExpenseCategory 新建账单分类
	// (POST /expense-categories)
	CreateExpenseCategory(ctx context.Context, request CreateExpenseCategoryRequestObject) (CreateExpenseCategoryResponseObject, error)
	// DeleteExpenseCategory 软删除；仍被账目引用时返回 409 CATEGORY_IN_USE
	// (DELETE /expense-categories/{category_id})
	DeleteExpenseCategory(ctx context.Context, request DeleteExpenseCategoryRequestObject) (DeleteExpenseCategoryResponseObject, error)
	// GetExpenseCategory 单个账单分类
	// (GET /expense-categories/{category_id})
	GetExpenseCategory(ctx context.Context, request GetExpenseCategoryRequestObject) (GetExpenseCategoryResponseObject, error)
	// UpdateExpenseCategory 改名、改图标或排序
	// (PATCH /expense-categories/{category_id})
	UpdateExpenseCategory(ctx context.Context, request UpdateExpenseCategoryRequestObject) (UpdateExpenseCategoryResponseObject, error)
	// SearchPlaces 搜索高德兴趣点，最多 20 个可定位结果
	// (GET /geo/places)
	SearchPlaces(ctx context.Context, request SearchPlacesRequestObject) (SearchPlacesResponseObject, error)
	// ReverseGeocode 将 GCJ-02 坐标解析为地点名与地址
	// (GET /geo/reverse-geocode)
	ReverseGeocode(ctx context.Context, request ReverseGeocodeRequestObject) (ReverseGeocodeResponseObject, error)
	// CalculateRoute 计算两点间的道路距离、预计时长和路线
	// (GET /geo/routes)
	CalculateRoute(ctx context.Context, request CalculateRouteRequestObject) (CalculateRouteResponseObject, error)
	// CalculateTripRoutes 一次算出整趟行程的相邻路段
	// (GET /geo/trip-routes)
	CalculateTripRoutes(ctx context.Context, request CalculateTripRoutesRequestObject) (CalculateTripRoutesResponseObject, error)
	// GetMetadata 公开固定枚举、币种精度、上传上限与协议版本
	// (GET /metadata)
	GetMetadata(ctx context.Context, request GetMetadataRequestObject) (GetMetadataResponseObject, error)
	// ListPackingLibrary 内置物品库的版本、分类与物品；随程序发布，不落库
	// (GET /packing-library)
	ListPackingLibrary(ctx context.Context, request ListPackingLibraryRequestObject) (ListPackingLibraryResponseObject, error)
	// ListSharedItineraryItems 访客读取分享旅行的行程骨架，键集分页
	// (GET /public/itinerary-items)
	ListSharedItineraryItems(ctx context.Context, request ListSharedItineraryItemsRequestObject) (ListSharedItineraryItemsResponseObject, error)
	// GetSharedRoutes 服务端按行程顺序计算全部相邻路段；访客不能指定坐标
	// (GET /public/routes)
	GetSharedRoutes(ctx context.Context, request GetSharedRoutesRequestObject) (GetSharedRoutesResponseObject, error)
	// GetSharedTrip 访客读取分享旅行的基本信息；每次调用计一次访问
	// (GET /public/trip)
	GetSharedTrip(ctx context.Context, request GetSharedTripRequestObject) (GetSharedTripResponseObject, error)
	// ListTrashedTrips 回收站旅行；按删除时间倒序，返回恢复截止时间与永久清理状态
	// (GET /recycle-bin/trips)
	ListTrashedTrips(ctx context.Context, request ListTrashedTripsRequestObject) (ListTrashedTripsResponseObject, error)
	// GetTrashedTrip 本人回收站中的旅行，提供最新版本；不在回收站的旅行返回 404
	// (GET /recycle-bin/trips/{trip_id})
	GetTrashedTrip(ctx context.Context, request GetTrashedTripRequestObject) (GetTrashedTripResponseObject, error)
	// PurgeTrip 请求永久清理；需要近期密码复验与明确确认，affected 中返回清理任务
	// (POST /recycle-bin/trips/{trip_id}/purge)
	PurgeTrip(ctx context.Context, request PurgeTripRequestObject) (PurgeTripResponseObject, error)
	// RestoreTrip 恢复整趟旅行；须在 purge_after_at 前且未请求永久清理，否则 409 RESTORE_UNAVAILABLE
	// (POST /recycle-bin/trips/{trip_id}/restore)
	RestoreTrip(ctx context.Context, request RestoreTripRequestObject) (RestoreTripResponseObject, error)
	// ListTrips 有效旅行列表；按阶段、归档、名称或目的地筛选，键集分页
	// (GET /trips)
	ListTrips(ctx context.Context, request ListTripsRequestObject) (ListTripsResponseObject, error)
	// CreateTrip 新建旅行；币种默认 CNY，时区默认账号默认时区
	// (POST /trips)
	CreateTrip(ctx context.Context, request CreateTripRequestObject) (CreateTripResponseObject, error)
	// TrashTrip 整趟旅行进入回收站（30 天内可恢复）；要求版本相等
	// (DELETE /trips/{trip_id})
	TrashTrip(ctx context.Context, request TrashTripRequestObject) (TrashTripResponseObject, error)
	// GetTrip 单个旅行的规范资源；回收站中的旅行返回 410 TRIP_DELETED
	// (GET /trips/{trip_id})
	GetTrip(ctx context.Context, request GetTripRequestObject) (GetTripResponseObject, error)
	// UpdateTrip 局部更新；字段级合并，日期修改保留原行程，总预算在此修改
	// (PATCH /trips/{trip_id})
	UpdateTrip(ctx context.Context, request UpdateTripRequestObject) (UpdateTripResponseObject, error)
	// SetTripArchived 归档或取消归档；归档后仍允许修正；要求版本相等
	// (POST /trips/{trip_id}/archive)
	SetTripArchived(ctx context.Context, request SetTripArchivedRequestObject) (SetTripArchivedResponseObject, error)
	// ListTripAssets 按状态或 ID 集合查询本旅行资产，供恢复上传状态与批量核对
	// (GET /trips/{trip_id}/assets)
	ListTripAssets(ctx context.Context, request ListTripAssetsRequestObject) (ListTripAssetsResponseObject, error)
	// ListItineraryItems 旅行的行程项目列表；按日期区间与状态筛选，键集分页
	// (GET /trips/{trip_id}/itinerary-items)
	ListItineraryItems(ctx context.Context, request ListItineraryItemsRequestObject) (ListItineraryItemsResponseObject, error)
	// CreateItineraryItem 新建行程项目；默认追加到当天末尾
	// (POST /trips/{trip_id}/itinerary-items)
	CreateItineraryItem(ctx context.Context, request CreateItineraryItemRequestObject) (CreateItineraryItemResponseObject, error)
	// ReorderItineraryItems 重排受影响日期的行程；支持跨日移动，整体在一个事务中完成
	// (POST /trips/{trip_id}/itinerary-items/reorder)
	ReorderItineraryItems(ctx context.Context, request ReorderItineraryItemsRequestObject) (ReorderItineraryItemsResponseObject, error)
	// DeleteItineraryItem 软删除本项目，不影响其他记录；要求版本相等
	// (DELETE /trips/{trip_id}/itinerary-items/{item_id})
	DeleteItineraryItem(ctx context.Context, request DeleteItineraryItemRequestObject) (DeleteItineraryItemResponseObject, error)
	// GetItineraryItem 单个行程项目的规范资源
	// (GET /trips/{trip_id}/itinerary-items/{item_id})
	GetItineraryItem(ctx context.Context, request GetItineraryItemRequestObject) (GetItineraryItemResponseObject, error)
	// UpdateItineraryItem 局部更新内容与状态；跨日移动与排序走重排接口
	// (PATCH /trips/{trip_id}/itinerary-items/{item_id})
	UpdateItineraryItem(ctx context.Context, request UpdateItineraryItemRequestObject) (UpdateItineraryItemResponseObject, error)
	// ListLedgerEntries 旅行的账目列表；按实际日期、分类、类型及关联筛选，键集分页
	// (GET /trips/{trip_id}/ledger-entries)
	ListLedgerEntries(ctx context.Context, request ListLedgerEntriesRequestObject) (ListLedgerEntriesResponseObject, error)
	// CreateLedgerEntry 记录支出或退款；校验币种、分类有效与原支出关系，第一条有效账目锁定旅行币种
	// (POST /trips/{trip_id}/ledger-entries)
	CreateLedgerEntry(ctx context.Context, request CreateLedgerEntryRequestObject) (CreateLedgerEntryResponseObject, error)
	// DeleteLedgerEntry 软删除；删除原支出时同事务解除其关联退款并进入 affected（warnings 含 REFUNDS_UNLINKED），最后一条账目删除后解锁旅行币种
	// (DELETE /trips/{trip_id}/ledger-entries/{entry_id})
	DeleteLedgerEntry(ctx context.Context, request DeleteLedgerEntryRequestObject) (DeleteLedgerEntryResponseObject, error)
	// GetLedgerEntry 单条账目，含票据资产 ID，不含临时下载地址
	// (GET /trips/{trip_id}/ledger-entries/{entry_id})
	GetLedgerEntry(ctx context.Context, request GetLedgerEntryRequestObject) (GetLedgerEntryResponseObject, error)
	// UpdateLedgerEntry 局部更新；类型不可改，修改金额与分类须与关联退款保持一致
	// (PATCH /trips/{trip_id}/ledger-entries/{entry_id})
	UpdateLedgerEntry(ctx context.Context, request UpdateLedgerEntryRequestObject) (UpdateLedgerEntryResponseObject, error)
	// ListPackingItems 旅行的行李清单；按分类与状态筛选，键集分页
	// (GET /trips/{trip_id}/packing-items)
	ListPackingItems(ctx context.Context, request ListPackingItemsRequestObject) (ListPackingItemsResponseObject, error)
	// CreatePackingItem 创建独立物品；同分类同名冲突返回 422
	// (POST /trips/{trip_id}/packing-items)
	CreatePackingItem(ctx context.Context, request CreatePackingItemRequestObject) (CreatePackingItemResponseObject, error)
	// CreatePackingItems 一个事务批量创建最多 100 件物品；同分类同名与请求内重复项跳过
	// (POST /trips/{trip_id}/packing-items/batch)
	CreatePackingItems(ctx context.Context, request CreatePackingItemsRequestObject) (CreatePackingItemsResponseObject, error)
	// DeletePackingItem 软删除物品；要求版本相等
	// (DELETE /trips/{trip_id}/packing-items/{item_id})
	DeletePackingItem(ctx context.Context, request DeletePackingItemRequestObject) (DeletePackingItemResponseObject, error)
	// GetPackingItem 单件物品的规范资源
	// (GET /trips/{trip_id}/packing-items/{item_id})
	GetPackingItem(ctx context.Context, request GetPackingItemRequestObject) (GetPackingItemResponseObject, error)
	// UpdatePackingItem 局部更新；内容编辑与状态变化使用同一业务规则
	// (PATCH /trips/{trip_id}/packing-items/{item_id})
	UpdatePackingItem(ctx context.Context, request UpdatePackingItemRequestObject) (UpdatePackingItemResponseObject, error)
	// DisableTripShare 关闭分享，旧链接立即失效；未开启也返回 204
	// (DELETE /trips/{trip_id}/share)
	DisableTripShare(ctx context.Context, request DisableTripShareRequestObject) (DisableTripShareResponseObject, error)
	// GetTripShare 读取旅行的分享链接；未开启返回 404 SHARE_NOT_FOUND
	// (GET /trips/{trip_id}/share)
	GetTripShare(ctx context.Context, request GetTripShareRequestObject) (GetTripShareResponseObject, error)
	// EnableTripShare 开启分享；已开启时原样返回。分享不进入同步体系，不带幂等键与 If-Match
	// (PUT /trips/{trip_id}/share)
	EnableTripShare(ctx context.Context, request EnableTripShareRequestObject) (EnableTripShareResponseObject, error)
	// RotateTripShare 重新生成分享令牌，旧链接立即失效；未开启返回 404 SHARE_NOT_FOUND
	// (POST /trips/{trip_id}/share/rotate)
	RotateTripShare(ctx context.Context, request RotateTripShareRequestObject) (RotateTripShareResponseObject, error)
	// GetTripStatistics 旅行开支统计：总额、分类汇总与占比、每日明细摘要及总预算对比
	// (GET /trips/{trip_id}/statistics)
	GetTripStatistics(ctx context.Context, request GetTripStatisticsRequestObject) (GetTripStatisticsResponseObject, error)
	// ListTodos 旅行的待办列表；全部、未完成、已完成或逾期，键集分页
	// (GET /trips/{trip_id}/todos)
	ListTodos(ctx context.Context, request ListTodosRequestObject) (ListTodosResponseObject, error)
	// CreateTodo 创建待办
	// (POST /trips/{trip_id}/todos)
	CreateTodo(ctx context.Context, request CreateTodoRequestObject) (CreateTodoResponseObject, error)
	// DeleteTodo 软删除待办；要求版本相等
	// (DELETE /trips/{trip_id}/todos/{todo_id})
	DeleteTodo(ctx context.Context, request DeleteTodoRequestObject) (DeleteTodoResponseObject, error)
	// GetTodo 单个待办的规范资源；逾期标识由列表上下文计算
	// (GET /trips/{trip_id}/todos/{todo_id})
	GetTodo(ctx context.Context, request GetTodoRequestObject) (GetTodoResponseObject, error)
	// UpdateTodo 局部更新；completed 可设为 true 或 false，completed_at 由服务端维护
	// (PATCH /trips/{trip_id}/todos/{todo_id})
	UpdateTodo(ctx context.Context, request UpdateTodoRequestObject) (UpdateTodoResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

